 const min=[0,1,2].map(axis=>Math.min(...flat.map(p=>p[axis]))),max=[0,1,2].map(axis=>Math.max(...flat.map(p=>p[axis])));
 const scale=1.65/Math.max(...max.map((v,i)=>v-min[i]));
